  "Your rights": "Vos droits",
  "Cookies": "Cookies",
  "When you fill in a form on this site, we collect your work email and, if you choose to add it, a short description of your question. The diagnostic also records your answers and score.": "Quand vous remplissez un formulaire sur ce site, nous collectons votre e-mail professionnel et, si vous l'ajoutez, une courte description de votre question. Le diagnostic enregistre aussi vos réponses et votre score.",
  "To reply to you, send you what you asked for (guide, readout, meeting invitation) and, if you subscribed, our newsletter. Legal basis: your consent, and our legitimate interest in answering a request you made.": "Pour vous répondre, vous envoyer ce que vous avez demandé (guide, restitution, invitation) et, si vous y êtes inscrit, notre newsletter. Base légale : votre consentement, et notre intérêt légitime à répondre à votre demande.",
  "The Licter team only, and the tools we use to run it: [CRM, email and calendar providers]. We do not sell or rent your data.": "L'équipe Licter uniquement, et les outils que nous utilisons pour cela : [CRM, e-mail, agenda]. Nous ne vendons ni ne louons vos données.",
  "[Duration, e.g. three years after our last exchange], then it is deleted.": "[Durée, par exemple trois ans après notre dernier échange], puis elles sont supprimées.",
  "You can access, correct or delete your data, object to its use, or withdraw your consent at any time by writing to [email address]. Each email we send has an unsubscribe link. You can also contact the CNIL (cnil.fr).": "Vous pouvez accéder à vos données, les rectifier ou les supprimer, vous opposer à leur usage ou retirer votre consentement à tout moment en écrivant à [adresse e-mail]. Chaque e-mail envoyé contient un lien de désinscription. Vous pouvez aussi saisir la CNIL (cnil.fr).",
  "[To complete once the analytics tool is chosen. This version of the site sets no tracking cookie; the language choice is stored in your browser only.]": "[À compléter une fois l'outil de mesure d'audience choisi. Cette version du site ne dépose aucun cookie de suivi ; le choix de langue est seulement stocké dans votre navigateur.]",
  "We use your email only to reply to you.": "Votre e-mail sert uniquement à vous répondre.",
