  "posts read in three weeks, across four markets and four languages": "publications lues en trois semaines, sur quatre marchés et dans quatre langues",
  "A food group was about to change the recipe of its best seller.": "Un groupe agroalimentaire s'apprêtait à changer la recette de son best-seller.",
  "The question": "La question",
