  "Illustrative example. Every readout is written by the analyst who ran the study.": "Exemple illustratif. Chaque restitution est rédigée par l'analyste qui a mené l'étude.",
  "Did the spring campaign move anything beyond the paid reach?": "La campagne de printemps a-t-elle fait bouger quelque chose au-delà de la portée payée ?",
  "Creators carried most of the reach. The brand's own posts, very little.": "Les créateurs ont porté l'essentiel de la portée. Les publications de la marque, très peu.",
  "The conversation spread into two communities the brief had not targeted.": "La conversation a gagné deux communautés que le brief ne visait pas.",
  "Paid amplification stopped adding reach after the third week.": "L'amplification payée n'ajoutait plus de portée après la troisième semaine.",
  "Move a third of the paid budget to creator partnerships for the autumn launch.": "Basculer un tiers du budget payé vers des partenariats créateurs pour le lancement d'automne.",
  "Is the drop in sentiment a crisis, or a bad week?": "La baisse du sentiment, crise ou mauvaise semaine ?",
  "Negative posts tripled, but most of them came from a single community.": "Les publications négatives ont triplé, mais la plupart venaient d'une seule communauté.",
  "Search interest in the brand did not move.": "L'intérêt de recherche pour la marque n'a pas bougé.",
  "The complaint was about delivery times, not the product.": "La plainte portait sur les délais de livraison, pas sur le produit.",
  "Fix the delivery message. No crisis communication needed.": "Corriger le message sur la livraison. Pas de communication de crise.",
  "Who is our core target, really?": "Qui est vraiment notre cœur de cible ?",
  "The buyers are about ten years younger than the brand's personas.": "Les acheteurs ont une dizaine d'années de moins que les personas de la marque.",
  "They follow cooking creators, not fashion ones.": "Ils suivent des créateurs cuisine, pas mode.",
  "They ask generative AI for a recommendation before they search.": "Ils demandent une recommandation à l'IA générative avant de chercher.",
  "Rebuild the personas and move the media plan toward food creators.": "Refaire les personas et orienter le plan média vers les créateurs food.",
  "Is the high-protein trend worth a product line?": "La tendance protéinée mérite-t-elle une gamme ?",
  "Mentions have grown steadily for eighteen months, in three countries.": "Les mentions progressent depuis dix-huit mois, dans trois pays.",
  "The topic moved from gym communities to parents.": "Le sujet est passé des communautés sportives aux parents.",
  "The unmet need is taste, not protein content.": "Le besoin non couvert, c'est le goût, pas la teneur en protéines.",
  "Launch a pilot range in one market, positioned on taste.": "Lancer une gamme pilote sur un marché, positionnée sur le goût.",
