  "a one-page brief: the decision, the question, the perimeter.": "un brief d'une page : la décision, la question, le périmètre.",
  "the source plan: platforms, markets, languages, period.": "le plan de sources : plateformes, marchés, langues, période.",
  "working sessions with the analyst, not a report in your inbox.": "des séances de travail avec l'analyste, pas un rapport dans votre boîte mail.",
  "a recommendation, presented to the people who decide.": "une recommandation, présentée à celles et ceux qui décident.",
  "Social listening, audience intelligence, digital panel and search listening, combined and filtered by consultants rather than by a dashboard default.": "Social listening, audience intelligence, panel digital et search listening, combinés et filtrés par des consultants plutôt que par un réglage d'usine.",
  "Where does your listening stand?": "Où en est votre écoute ?",
  "Six questions, three minutes. Your score now, the full readout by email.": "Six questions, trois minutes. Votre score tout de suite, le détail par e-mail.",
  "Twelve questions social data answers better than a survey.": "Douze questions auxquelles la social data répond mieux qu'une étude.",
  "Three are open below. Leave your email and the other nine open here, with the full guide sent to you.": "Trois sont ouvertes ci-dessous. Laissez votre e-mail : les neuf autres s'ouvrent ici, et le guide complet vous est envoyé.",
  "NOTED, THE GUIDE IS ON ITS WAY": "C'EST NOTÉ, LE GUIDE ARRIVE",
