  "(optional)": "(facultatif)",
  "Licter is the Social Data Intelligence consultancy. We turn what people post, search and ask AI into decisions.":
    "Licter est le cabinet de conseil en Social Data Intelligence. Nous transformons ce que les gens publient, cherchent et demandent à l'IA en décisions.",
